<script>
    function mover_img(este,aeste){
        var f=document.createElement('form'); f.method='POST'; f.action='?page=visitantes&mode=editar&id=<?= (int)$_GET["id"]; ?>';
        [['mover',este],['aeste',aeste],['move_key',crypto.randomUUID().replace(/-/g,'')],['csrf','<?= htmlspecialchars(rf_csrf_token(), ENT_QUOTES); ?>']].forEach(function(x){var i=document.createElement('input');i.type='hidden';i.name=x[0];i.value=x[1];f.appendChild(i);});
        document.body.appendChild(f); f.submit();
    }

    // --- P4: separar en bloque (proveniencia exacta) ---
    function rfActualizarConteo(){
        var checks = document.querySelectorAll(".rf-foto-check:checked");
        var el = document.getElementById("rf_sel_count");
        if (el) { el.textContent = checks.length + " foto(s) seleccionada(s)"; }
    }
    function rfMostrarCargando(){
        var d = document.getElementById("rf-cargando");
        if (d) { return; }
        d = document.createElement("div");
        d.id = "rf-cargando";
        d.style.cssText = "position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9999;" +
            "display:flex;align-items:center;justify-content:center;color:#fff;font-weight:600;font-size:1.05rem";
        d.textContent = "Aplicando corrección a la biblioteca…";
        document.body.appendChild(d);
    }
    function rfSepararSeleccionadas(){
        var checks = document.querySelectorAll(".rf-foto-check:checked");
        if (checks.length === 0) { alert("Selecciona al menos una foto"); return; }
        var destino = document.getElementById("separar_destino").value;
        var ids = [];
        checks.forEach(function(c){ ids.push(c.getAttribute("data-fid")); });
        var ok = confirm("¿Mover " + ids.length + " foto(s) a la persona seleccionada?\n" +
            "Se quitará de la biblioteca de esta persona exactamente lo que aportaron (sin residuos).");
        if (!ok) { return; }
        rfMostrarCargando();
        var f=document.createElement('form'); f.method='POST'; f.action='?page=visitantes&mode=editar&id=<?= (int)$_GET["id"]; ?>';
        [['separar',ids.join(',')],['aeste',destino],['move_key',crypto.randomUUID().replace(/-/g,'')],['csrf','<?= htmlspecialchars(rf_csrf_token(), ENT_QUOTES); ?>']].forEach(function(x){var i=document.createElement('input');i.type='hidden';i.name=x[0];i.value=x[1];f.appendChild(i);});
        document.body.appendChild(f); f.submit();
    }
    
    
   function buscar1(){
       var camara = document.getElementById("camara").value;
       var desde = document.getElementById("desde").value;
       var hasta = document.getElementById("hasta").value;
       var trabajador = document.getElementById("trabajador").checked ? 1 : 0;
       var buscador = document.getElementById("buscador");
       var params = [
           "page=visitantes",
           "buscar=1",
           "camara=" + encodeURIComponent(camara),
           "trabajador=" + trabajador
       ];

       // No enviar fechas vacías evita convertirlas accidentalmente en un rango.
       if (desde.trim() !== "") { params.push("desde=" + encodeURIComponent(desde)); }
       if (hasta.trim() !== "") { params.push("hasta=" + encodeURIComponent(hasta)); }
       if (buscador && buscador.value.trim() !== "") {
           params.push("buscador=" + encodeURIComponent(buscador.value.trim()));
       }

       location.href = "?" + params.join("&");

   } 
   
   function cambiar_nombre(valor,persona_id){
       //medianbte ajax guardo el nombre mientras, muestro el iocono de cargando
            
            cargador=document.getElementById("cargador"+persona_id);
            cargador.setAttribute("style","display:inline");
            
            ajax = nuevoAjax();
             urlllamada="pages/visitantes/acciones_ajax.php?a=1";
             ajax.open("POST", urlllamada, true);
             ajax.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    
                    sleep(2000);
                    cargador.setAttribute("style","display:none");
                }
            }
             ajax.send("persona_id="+encodeURIComponent(persona_id)+"&valor="+encodeURIComponent(valor)+"&csrf=<?= htmlspecialchars(rf_csrf_token(), ENT_QUOTES); ?>");
       
   }
   
   function cambiar_trabajador(persona_id){
       
        cargador=document.getElementById("cargador2"+persona_id);
        cargador.setAttribute("style","display:inline");

       
        trabajador_edit=document.getElementById("trabajador_edit");
       
       trabajador=0;
       if(trabajador_edit.checked){
           trabajador=1;
       }else{
           trabajador=0;
       }
       
       
        ajax = nuevoAjax();
         urlllamada="pages/visitantes/acciones_ajax.php?a=2";
         ajax.open("POST", urlllamada, true);
         ajax.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {

                sleep(2000);
                cargador.setAttribute("style","display:none");
            }
        }
         ajax.send("persona_id="+encodeURIComponent(persona_id)+"&valor="+trabajador+"&csrf=<?= htmlspecialchars(rf_csrf_token(), ENT_QUOTES); ?>");
       
       
   }
   
    function sleep(ms) {
      return new Promise(resolve => setTimeout(resolve, ms));
    }
    
    
    


    
    
</script>
